import java.net.URI;
import java.net.http.*;
import java.net.http.HttpResponse.BodyHandlers;

public class SpellApiClient {

    // Simulated HTTP client for sandbox
    static HttpClient client = HttpClient.newHttpClient();

    public static void main(String[] args) throws Exception {
        // 1. GET /api/spells/1
        HttpRequest getReq = HttpRequest.newBuilder()
            .uri(URI.create("https://httpbin.org/status/200"))
            .GET()
            .build();
        HttpResponse<String> getResp = client.send(getReq, BodyHandlers.ofString());
        System.out.println(getResp.statusCode());

        // 2. POST with JSON body
        String json = "{\"name\":\"Icestorm\",\"damage\":95}";
        HttpRequest postReq = HttpRequest.newBuilder()
            .uri(URI.create("https://httpbin.org/status/201"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(json))
            .build();
        HttpResponse<String> postResp = client.send(postReq, BodyHandlers.ofString());
        System.out.println(postResp.statusCode());

        // 3. Conditional print
        if (getResp.statusCode() == 200) {
            System.out.println("Found spell");
        } else if (getResp.statusCode() == 404) {
            System.out.println("Not found");
        }
    }
}
